public final class MainActivity extends Activity {
 private static final String SITE="https://iemfaraz.github.io/faraz-pharmacy/", HOME=SITE+"?app=android";
 private WebView home,tracking,web;
 private FrameLayout content;
 private ProgressBar progress;
 private LinearLayout error;
 private TextView status;
 private final List<Button> tabs=new ArrayList<>();
 private ValueCallback<Uri[]> chooser;
 private GeolocationPermissions.Callback locationCallback;
 private String locationOrigin;
 private byte[] pendingDownload;
 private final int green=Color.rgb(20,99,78);
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}
 private boolean trusted(String value){try{Uri u=Uri.parse(value);return "https".equals(u.getScheme())&&"iemfaraz.github.io".equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443)&&u.getPath()!=null&&u.getPath().startsWith("/faraz-pharmacy/");}catch(Exception e){return false;}}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(251,252,248));
  if(Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets s=insets.getInsets(WindowInsets.Type.systemBars());android.graphics.Insets k=insets.getInsets(WindowInsets.Type.ime());v.setPadding(s.left,s.top,s.right,Math.max(s.bottom,k.bottom));return insets;});else root.setFitsSystemWindows(true);
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(16),dp(10),dp(8),dp(10));bar.setBackgroundColor(green);
  ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.ic_pharmacy);icon.setContentDescription("Faraz Pharmacy logo");bar.addView(icon,new LinearLayout.LayoutParams(dp(42),dp(42)));
  LinearLayout names=new LinearLayout(this);names.setOrientation(1);names.setPadding(dp(12),0,0,0);TextView title=text("Faraz Pharmacy",19,Color.WHITE);title.setTypeface(null,1);names.addView(title);names.addView(text("Barikot · Swat",12,Color.rgb(215,234,203)));bar.addView(names,new LinearLayout.LayoutParams(0,-2,1));Button menu=new Button(this);menu.setText("⋮");menu.setTextSize(25);menu.setContentDescription("More options");bar.addView(menu,new LinearLayout.LayoutParams(dp(48),dp(48)));menu.setOnClickListener(v->menu(menu));root.addView(bar);
  progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));
  status=text("Secure connection to Faraz Pharmacy",11,green);status.setPadding(dp(16),dp(6),dp(12),dp(6));root.addView(status);
  content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));home=createWebView();web=home;content.addView(home,new FrameLayout.LayoutParams(-1,-1));
  error=new LinearLayout(this);error.setOrientation(1);error.setGravity(Gravity.CENTER);error.setPadding(dp(28),dp(28),dp(28),dp(28));error.setBackgroundColor(Color.rgb(251,252,248));error.addView(text("Let’s reconnect",24,green));TextView msg=text("Internet is required to browse products, submit requests and view quotations. Check your connection and try again.",15,Color.DKGRAY);msg.setGravity(Gravity.CENTER);error.addView(msg);Button retry=new Button(this);retry.setText("Try again");error.addView(retry);retry.setOnClickListener(v->{error.setVisibility(View.GONE);web.reload();});error.setVisibility(View.GONE);content.addView(error,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout bottom=new LinearLayout(this);bottom.setPadding(dp(4),dp(4),dp(4),dp(4));String[] labels={"Home","Request","Track","Contact"};for(int i=0;i<labels.length;i++){final int tab=i;Button b=new Button(this);b.setText(labels[i]);b.setTextSize(12);b.setAllCaps(false);b.setContentDescription(labels[i]);bottom.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));tabs.add(b);b.setOnClickListener(v->select(tab));}root.addView(bottom);setContentView(root);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);select(0);
 }
 private WebView createWebView(){WebView w=new WebView(this);w.setBackgroundColor(Color.rgb(251,252,248));WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setGeolocationEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);s.setSafeBrowsingEnabled(true);s.setUserAgentString(s.getUserAgentString()+" FarazPharmacyAndroid/1.0");CookieManager.getInstance().setAcceptThirdPartyCookies(w,false);w.addJavascriptInterface(new Downloads(),"FarazDownloads");
  w.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest r){String url=r.getUrl().toString();if(trusted(url)){if(Uri.parse(url).getPath().endsWith("track.html")&&view==home){select(2);tracking.loadUrl(url);return true;}return false;}if(r.isForMainFrame())external(url);return true;}
   @Override public void onPageStarted(WebView v,String url,android.graphics.Bitmap favicon){if(v==web){progress.setVisibility(View.VISIBLE);error.setVisibility(View.GONE);status.setText("Connecting securely…");}}
   @Override public void onPageFinished(WebView v,String url){if(v==web){progress.setVisibility(View.GONE);status.setText(url.contains("track.html")?"Track requests · View quotations":"Orders go directly to the pharmacy dashboard");}if(trusted(url))v.evaluateJavascript("(function(){if(!document.getElementById('faraz-native-style')){var s=document.createElement('style');s.id='faraz-native-style';s.textContent='body>header,.utility,.mobile-dock{display:none!important}html{scroll-padding-top:16px}footer{padding-bottom:28px!important}';document.head.appendChild(s)}window.print=function(){FarazDownloads.print()}})()",null);}
   @Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame()&&v==web){progress.setVisibility(View.GONE);error.setVisibility(View.VISIBLE);status.setText("Connection unavailable");}}
  });
  w.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView v,int n){if(v==web)progress.setProgress(n);}
   @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;try{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("image/*");intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","image/webp"});intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(intent,51);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;Toast.makeText(MainActivity.this,"No photo picker is available on this phone.",Toast.LENGTH_LONG).show();}return true;}
   @Override public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback callback){if(!trusted(w.getUrl())||!"https://iemfaraz.github.io".equals(origin.replaceAll("/$",""))){callback.invoke(origin,false,false);return;}if(locationCallback!=null)locationCallback.invoke(locationOrigin,false,false);locationCallback=callback;locationOrigin=origin;
    if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(MainActivity.this).setTitle("Share delivery location?").setMessage("Allow this website to capture one location pin for your delivery request? The pin is sent to Faraz Pharmacy only when you submit. You can choose pharmacy collection instead.").setPositiveButton("Allow once",(d,which)->finishLocation(true)).setNegativeButton("Not now",(d,which)->finishLocation(false)).setOnCancelListener(d->finishLocation(false)).show();}else requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},52);
   }
   @Override public void onGeolocationPermissionsHidePrompt(){finishLocation(false);}
   @Override public boolean onJsAlert(WebView v,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("OK",(d,which)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}
  });
  w.setDownloadListener((url,ua,disposition,mime,length)->{if(!trusted(w.getUrl()))return;if(url.startsWith("blob:https://iemfaraz.github.io/")){String quoted=JSONObject.quote(url);w.evaluateJavascript("(async function(){try{var r=await fetch("+quoted+");var b=await r.blob();if(b.size>8*1024*1024){FarazDownloads.error('The file is too large. Open this page in your browser.');return}var f=new FileReader();f.onload=function(){FarazDownloads.save(String(f.result))};f.readAsDataURL(b)}catch(e){FarazDownloads.error('Download failed. Try Open in browser from the menu.')}})()",null);}else if(url.startsWith("https://"))external(url);});return w;
 }
 private void select(int index){if(index==3){new AlertDialog.Builder(this).setTitle("Contact Faraz Pharmacy").setItems(new String[]{"Chat on WhatsApp","Call +92 344 9006940"},(d,n)->external(n==0?"https://wa.me/923449006940":"tel:+923449006940")).show();return;}if(index==2){if(tracking==null){tracking=createWebView();content.addView(tracking,0,new FrameLayout.LayoutParams(-1,-1));tracking.loadUrl(SITE+"track.html?app=android");}web=tracking;if(trusted(home.getUrl()))home.evaluateJavascript("sessionStorage.getItem('faraz-tracking')",value->{try{String raw=new org.json.JSONArray("["+value+"]").getString(0);JSONObject receipt=new JSONObject(raw);String reference=receipt.getString("reference"),key=receipt.getString("key");if(reference.length()<60&&key.matches("[a-f0-9]{64}"))tracking.loadUrl(SITE+"track.html?app=android#reference="+Uri.encode(reference)+"&key="+key);}catch(Exception ignored){}});home.setVisibility(View.GONE);tracking.setVisibility(View.VISIBLE);}else{web=home;home.setVisibility(View.VISIBLE);if(tracking!=null)tracking.setVisibility(View.GONE);String destination=HOME+(index==1?"#order":"#home");if(home.getUrl()==null)home.loadUrl(destination);else home.loadUrl(destination);}error.setVisibility(View.GONE);status.setText(index==2?"Track requests · View quotations":"Orders go directly to the pharmacy dashboard");for(int i=0;i<tabs.size();i++){tabs.get(i).setTextColor(i==index?Color.WHITE:green);tabs.get(i).setBackgroundTintList(android.content.res.ColorStateList.valueOf(i==index?green:Color.rgb(235,242,225)));}}
 private void menu(View anchor){PopupMenu p=new PopupMenu(this,anchor);for(String t:new String[]{"Refresh page","Open in browser","Share pharmacy app","Privacy & app information"})p.getMenu().add(t);p.setOnMenuItemClickListener(item->{switch(item.getTitle().toString()){case "Refresh page":web.reload();break;case "Open in browser":external(web.getUrl()==null?HOME:web.getUrl());break;case "Share pharmacy app":Intent share=new Intent(Intent.ACTION_SEND);share.setType("text/plain");share.putExtra(Intent.EXTRA_TEXT,"Faraz Pharmacy — Barikot, Swat. Request medicines and track your enquiry: "+SITE+"android-app.html");startActivity(Intent.createChooser(share,"Share Faraz Pharmacy"));break;default:new AlertDialog.Builder(this).setTitle("Faraz Pharmacy 1.0.0").setMessage("In front of THQ Hospital, Barikot, Swat.\n\nInternet is required. Product availability, prices and delivery must be confirmed by the pharmacy. Requests are reviewed in the same private dashboard as the website.\n\nPhotos are chosen using your phone’s picker. Location is accessed only when you enable delivery location; no background location is requested. Saved delivery pins go to the pharmacy with your submitted request.\n\nThis app is distributed directly by the pharmacy and is not listed on Google Play. Do not enter medical history or identity documents.\n\nContact: +92 344 9006940").setPositiveButton("OK",null).show();}return true;});p.show();}
 private void external(String value){try{Uri u=Uri.parse(value);if(!Arrays.asList("https","tel","mailto","whatsapp").contains(u.getScheme()))return;startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(this,"No app is available to open this link.",Toast.LENGTH_LONG).show();}}
 private void finishLocation(boolean allow){if(locationCallback!=null){locationCallback.invoke(locationOrigin,allow,false);locationCallback=null;locationOrigin=null;}}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==52){boolean ok=false;for(int grant:grants)ok|=grant==PackageManager.PERMISSION_GRANTED;finishLocation(ok);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==51&&chooser!=null){Uri[] files=null;if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){int n=Math.min(3,data.getClipData().getItemCount());files=new Uri[n];for(int i=0;i<n;i++)files[i]=data.getClipData().getItemAt(i).getUri();}else if(data.getData()!=null)files=new Uri[]{data.getData()};}chooser.onReceiveValue(files);chooser=null;}if(request==53){byte[] bytes=pendingDownload;pendingDownload=null;if(result==RESULT_OK&&data!=null&&bytes!=null)try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new Exception();out.write(bytes);Toast.makeText(this,"File saved",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Could not save file. Please try again.",Toast.LENGTH_LONG).show();}}}
 public final class Downloads{
  @JavascriptInterface public void print(){runOnUiThread(()->{if(trusted(web.getUrl())){android.print.PrintManager pm=(android.print.PrintManager)getSystemService(PRINT_SERVICE);pm.print("Faraz Pharmacy quotation",web.createPrintDocumentAdapter("Faraz Pharmacy quotation"),new android.print.PrintAttributes.Builder().setMediaSize(android.print.PrintAttributes.MediaSize.ISO_A4).build());}});}
  @JavascriptInterface public void error(String message){runOnUiThread(()->Toast.makeText(MainActivity.this,message,Toast.LENGTH_LONG).show());}
  @JavascriptInterface public void save(String data){if(data==null||data.length()>12*1024*1024)return;runOnUiThread(()->{if(!trusted(web.getUrl())||pendingDownload!=null)return;try{int comma=data.indexOf(',');String type=data.substring(0,comma);boolean pdf=type.equals("data:application/pdf;base64"),plain=type.equals("data:text/plain;base64")||type.equals("data:text/plain;charset=utf-8;base64");if(!pdf&&!plain)return;byte[] bytes=Base64.decode(data.substring(comma+1),Base64.DEFAULT);if(bytes.length>8*1024*1024)return;if(pdf&&(bytes.length<5||bytes[0]!='%'||bytes[1]!='P'||bytes[2]!='D'||bytes[3]!='F'||bytes[4]!='-'))return;pendingDownload=bytes;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT);save.addCategory(Intent.CATEGORY_OPENABLE);save.setType(pdf?"application/pdf":"text/plain");save.putExtra(Intent.EXTRA_TITLE,pdf?"Faraz-Pharmacy-Quotation.pdf":"Faraz-Pharmacy-Tracking.txt");startActivityForResult(save,53);}catch(Exception e){pendingDownload=null;Toast.makeText(MainActivity.this,"Use Open in browser to save this file.",Toast.LENGTH_LONG).show();}});}
 }
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else if(web==tracking)select(0);else new AlertDialog.Builder(this).setTitle("Close Faraz Pharmacy?").setMessage("Any request you have not submitted will be lost.").setPositiveButton("Close",(d,w)->finish()).setNegativeButton("Stay",null).show();}
 @Override protected void onDestroy(){finishLocation(false);if(chooser!=null)chooser.onReceiveValue(null);if(home!=null){home.removeJavascriptInterface("FarazDownloads");home.destroy();}if(tracking!=null){tracking.removeJavascriptInterface("FarazDownloads");tracking.destroy();}pendingDownload=null;super.onDestroy();}
}
